    bg.setAttribute('class', 'miga-art-bg'); bg.setAttribute('viewBox', '0 0 ' + W + ' ' + H);
    bg.setAttribute('preserveAspectRatio', 'xMaxYMid slice'); bg.setAttribute('aria-hidden', 'true'); bg.setAttribute('focusable', 'false');
    bg.innerHTML = a.bg;
    var fig = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
    fig.setAttribute('class', 'miga-figure'); fig.setAttribute('viewBox', '-4 -8 128 140');
    fig.setAttribute('aria-hidden', 'true'); fig.setAttribute('focusable', 'false');
